module freq_diveven (
    input clk, rst_n
);
// Parameter declaration(s)
parameter NUM_DIV = 6;
// Signal declaration(s)
reg [3:0] cnt;
reg clk_div;
// Behavioral description
always@(posedge clk or negedge rst_n) begin
    if(!rst_n) begin
        cnt <= 4'd0;
        clk_div <= 1'b0;
    end
    else begin
        if(cnt < ((NUM_DIV/2)-1)) begin
            cnt <= cnt + 1'b1;
        end
        else begin
            cnt <= 4'd0;
            clk_div <= ~clk_div;
        end
    end
end
endmodule
